insert into activities(slug, kind, title_ar, title_en, age_groups, activity_type, primary_dimension, dimensions, objectives, description_ar, description_en) values
  ('memory', 'memory', 'ذاكرة البطاقات', 'Memory Cards', array['7-8','9-10']::text[], 'game', 'cog', array['cog']::text[], array['memory','attention','concentration']::text[], 'تتدرّب على تذكّر أماكن البطاقات والانتباه للعبة.', 'Practises remembering where cards are and paying attention to the game.'),
  ('match', 'matching', 'طابق الصورة بالكلمة', 'Match the Picture', array['7-8']::text[], 'game', 'cog', array['cog']::text[], array['attention','memory']::text[], 'تربط الصورة باسمها، فتتدرّب على الانتباه والتذكّر.', 'Links each picture to its name, practising attention and recall.'),
  ('puzzle', 'puzzle', 'لعبة البازل', 'Puzzle Game', array['7-8','9-10','11-12']::text[], 'game', 'cog', array['cog','phy']::text[], array['reasoning','problem','concentration','finemotor','coordination']::text[], 'تخطّط لمكان كل قطعة وتحرّكها، فتتدرّب على حل المشكلات والتفكير البصري. اختر قطعًا أكثر لتحدٍّ أكبر (2–9 للأصغر، 9–25 للأوسط، 25–49 للأكبر).', 'Plans where each piece goes and moves it, practising problem-solving and visual reasoning. More pieces means a bigger challenge (2–9 younger, 9–25 middle, 25–49 older).'),
  ('coloring', 'coloring', 'ألبوم التلوين', 'Coloring Album', array['7-8','9-10']::text[], 'creative', 'phy', array['cog','emo','phy']::text[], array['finemotor','coordination','creativity','expression']::text[], 'تلوّن بحرية، فتتدرّب على التحكم بحركة اليد وتختار الألوان للتعبير عن نفسك.', 'Free colouring practises hand control and lets you choose colours to express yourself.'),
  ('drawing', 'drawing', 'لوحة الرسم', 'Drawing Canvas', array['7-8','9-10','11-12']::text[], 'creative', 'emo', array['cog','emo','phy']::text[], array['expression','creativity','finemotor','coordination']::text[], 'ترسم ما تشعر به أو تتخيّله، فتتدرّب على التعبير والإبداع وحركة اليد.', 'Draw what you feel or imagine, practising expression, creativity and hand control.'),
  ('story', 'story', 'قصة تفاعلية', 'Interactive Story', array['7-8','9-10']::text[], 'story', 'emo', array['emo','lif','soc']::text[], array['awareness','empathy','decision']::text[], 'تختار ما يفعله البطل مع غيمة حزينة، فتفكّر في مشاعر الآخرين وتتدرّب على الاختيار.', 'You choose what the hero does for a sad cloud, thinking about others’ feelings and practising choices.'),
  ('feelings', 'feelings', 'مشاعري', 'My Feelings', array['7-8','9-10','11-12']::text[], 'express', 'emo', array['emo','soc']::text[], array['recognition','expression','awareness','communication']::text[], 'تتعرّف على مشاعرك وتسمّيها وتخبر من تثق به بما تحتاج.', 'Notice and name your feelings, and tell someone you trust what you need.'),
  ('health', 'health', 'صحتي', 'My Health', array['7-8','9-10','11-12']::text[], 'express', 'lif', array['lif','soc']::text[], array['safety','communication','independence']::text[], 'تتعلّم أن تصف ما يشعر به جسمك وتخبر شخصًا كبيرًا، ويمكنك الرسم على مجسم جسم لتحديد المكان. هذه وسيلة للتواصل وليست اختبارًا.', 'Learn to describe how your body feels and tell a grown-up, and draw on a body model to show where. It is a way to communicate, not a test.'),
  ('wishes', 'wishes', 'أمنياتي الصغيرة', 'My Little Wishes', array['7-8','9-10','11-12']::text[], 'express', 'lif', array['lif','soc']::text[], array['decision','communication','independence']::text[], 'تختار ما تتمنّاه وتطلبه بكلماتك، فتتدرّب على اتخاذ القرار والتعبير عن حاجاتك.', 'Choose what you wish for and ask for it, practising decisions and speaking up for your needs.'),
  ('people', 'family', 'ناسي', 'My People', array['7-8','9-10','11-12']::text[], 'express', 'soc', array['soc']::text[], array['communication','cooperation']::text[], 'تتواصل مع عائلتك وتجرّب أنشطة مشتركة مثل الرسم معًا.', 'Stay in touch with your family and try shared activities such as drawing together.'),
  ('pets', 'pets', 'حيواناتي الأليفة', 'My Pets', array['7-8','9-10','11-12']::text[], 'care', 'lif', array['lif','soc']::text[], array['responsibility','empathy','decision','habits']::text[], 'تعتني بحيوانك: تختار طعامه ونظافته وراحته، فتتدرّب على المسؤولية وملاحظة احتياجات الآخرين.', 'Care for your pet by choosing food, cleaning and rest, practising responsibility and noticing others’ needs.'),
  ('journey', 'journal', 'رحلتي', 'My Journey', array['7-8','9-10','11-12']::text[], 'express', 'emo', array['emo']::text[], array['awareness','esteem','confidence']::text[], 'ترى ما صنعته وتتذكّره، فيدعم ذلك فخرك بعملك.', 'Looking back at what you made supports pride in your own work.'),
  ('acad-0', 'learning', 'لماذا ينبض قلبي؟', 'Why does my heart beat?', array['7-8','9-10','11-12']::text[], 'learn', 'cog', array['cog','lif']::text[], array['memory','independence']::text[], 'تتعلّم كيف يعمل قلبك وتتذكّر ما تعلّمته في سؤال قصير.', 'Learn how your heart works and recall it in a short question.'),
  ('acad-1', 'learning', 'غرفتي في المستشفى', 'My hospital room', array['7-8','9-10','11-12']::text[], 'learn', 'emo', array['emo','lif','soc']::text[], array['resilience','communication','independence']::text[], 'تتعرّف على غرفة المستشفى وتعرف أنك تستطيع أن تسأل عن أي شيء، فتستعدّ لموقف جديد.', 'Get to know a hospital room and learn you can ask about anything, preparing for a new situation.'),
  ('acad-2', 'learning', 'لماذا يقيس الممرض حرارتي؟', 'Why do nurses check my temperature?', array['7-8','9-10','11-12']::text[], 'learn', 'cog', array['cog','lif']::text[], array['reasoning','independence']::text[], 'تفهم لماذا يقيس الممرض الحرارة وما علاقتها بجسمك.', 'Understand why a nurse checks temperature and how it relates to your body.'),
  ('acad-3', 'learning', 'من هو ممرضي؟', 'Who is my nurse?', array['7-8','9-10','11-12']::text[], 'learn', 'soc', array['emo','soc']::text[], array['communication','respect','confidence']::text[], 'تتعرّف على دور الممرض وتتدرّب على إخباره عمّا يقلقك.', 'Learn what a nurse does and practise telling them what worries you.'),
  ('acad-4', 'learning', 'ما هو فحص الدم؟', 'What is a blood test?', array['7-8','9-10','11-12']::text[], 'learn', 'emo', array['emo','soc']::text[], array['regulation','communication','resilience']::text[], 'تعرف ما قد تشعر به في فحص الدم وأنك تستطيع أن تسأل، فتستعدّ بهدوء.', 'Learn what a blood test may feel like and that you can ask questions, to prepare calmly.'),
  ('acad-5', 'learning', 'من يقرر دوائي؟', 'Who decides my medicine?', array['7-8','9-10','11-12']::text[], 'learn', 'lif', array['lif']::text[], array['safety','responsibility']::text[], 'تتعلّم أن الطبيب والممرض هما من يقرران الدواء، وأن لا تأخذ دواءً وحدك.', 'Learn that your doctor and nurse decide your medicine and that you never take medicine alone.'),
  ('acad-6', 'learning', 'غسل اليدين', 'Washing my hands', array['7-8','9-10','11-12']::text[], 'learn', 'lif', array['lif','phy']::text[], array['habits','physhabits','independence']::text[], 'تتعلّم خطوات غسل اليدين كعادة صحية يومية.', 'Learn how to wash your hands as a daily healthy habit.'),
  ('acad-7', 'learning', 'عندما أشعر بالقلق', 'When I feel worried', array['7-8','9-10','11-12']::text[], 'learn', 'emo', array['emo','soc']::text[], array['awareness','regulation','expression','communication']::text[], 'تتعلّم أن القلق شعور طبيعي وما الذي يمكنك فعله حين تشعر به.', 'Learn that worry is a normal feeling and what you can do when you feel it.')
