create table if not exists developmental_objectives(
  key text primary key,
  dimension text not null check (dimension in ('cog','emo','soc','phy','lif')),
  label_ar text not null, label_en text not null);
on conflict (key) do nothing;
alter table activities add column if not exists slug text unique;
alter table activities add column if not exists activity_type text check (activity_type in ('game','creative','story','learn','express','care'));
alter table activities add column if not exists primary_dimension text check (primary_dimension in ('cog','emo','soc','phy','lif'));
alter table activities add column if not exists dimensions text[] not null default '{}' check (dimensions <@ array['cog','emo','soc','phy','lif']);
alter table activities add column if not exists objectives text[] not null default '{}';
alter table activities add column if not exists description_ar text;
alter table activities add column if not exists description_en text;
alter table activities drop constraint if exists activities_age_groups_check;
alter table activities add constraint activities_age_groups_check check (age_groups <@ array['5-7','8-10','7-8','9-10','11-12']) not valid; -- enforced for new and changed rows only; existing rows are not scanned or altered
alter table activities drop constraint if exists activities_kind_check;
alter table activities add constraint activities_kind_check check (kind in ('coloring', 'story', 'relaxation', 'puzzle', 'memory', 'matching', 'drawing', 'feelings', 'health', 'learning', 'wishes', 'family', 'pets', 'journal'));
create or replace function check_activity_objectives() returns trigger language plpgsql as $$
begin
  if exists (select 1 from unnest(new.objectives) o where o not in (select key from developmental_objectives)) then
    raise exception 'unknown developmental objective'; end if;
  if cardinality(new.objectives) > 0 and new.dimensions is distinct from (select coalesce(array_agg(distinct d.dimension order by d.dimension), '{}') from developmental_objectives d where d.key = any(new.objectives)) then
    raise exception 'dimensions must equal the dimensions of the objectives'; end if;
  return new;
end $$;
drop trigger if exists t_activity_objectives on activities;
create trigger t_activity_objectives before insert or update on activities for each row execute function check_activity_objectives();
on conflict (slug) do nothing;
alter table developmental_objectives enable row level security;
grant select on developmental_objectives to authenticated;
grant insert, update, delete on developmental_objectives to authenticated;
drop policy if exists do_sel on developmental_objectives;
drop policy if exists do_w on developmental_objectives;
create policy do_sel on developmental_objectives for select to authenticated using (true);
create policy do_w on developmental_objectives for all to authenticated using (is_admin()) with check (is_admin());
